var t=`1417-laplap`;var n=`world-1417`;var i=`VU`;var o=`oceania`;var l=6;var s=97;var r={en:`Laplap`,ua:`Лаплап`};var u={en:`Vanuatu laplap is traditionally grated tuber and coconut cream baked in banana leaves beneath hot stones; this is a home-oven taro version.`,ua:`Лаплап із Вануату традиційно готують із тертих коренеплодів та кокосових вершків у банановому листі під гарячим камінням; це домашня версія з таро.`};var m=[{en:`Peel edible taro, cut into chunks and boil in water until completely tender, 25–35 minutes; drain well. Never use wild taro.`,ua:`Очистіть харчове таро, наріжте шматками та варіть у воді до повної м’якості 25–35 хвилин; добре злийте воду. Не використовуйте дикоросле таро.`,t:[`boiling`,`draining`],m:35,i:[[`taro-root`,950,`g`],[`water`,1700,`ml`]]},{en:`Mash cooked taro thoroughly. Stir in coconut cream and salt to make a thick, spreadable mass.`,ua:`Ретельно розімніть приготовлене таро. Умішайте кокосові вершки й сіль до густої маси, яку можна розподілити шаром.`,t:[`mashing`,`mixing`],m:10,i:[[`coconut-cream`,350,`ml`],[`sea-salt`,5,`g`]]},{en:`Soften banana leaves with steam, then use them to line a baking dish. Spread in the taro mixture and fold leaves over the top.`,ua:`Розм’якшіть бананове листя парою та вистеліть ним форму. Викладіть масу з таро й загорніть листя зверху.`,t:[`leaf-wrapping`],m:12,i:[[`banana-leaf`,5,`leaf`]]},{en:`Bake covered at 180°C for 35–40 minutes until steaming hot and cohesive. Rest 10 minutes before slicing.`,ua:`Запікайте накритим при 180°C 35–40 хвилин, доки маса стане гарячою й щільною. Дайте постояти 10 хвилин перед нарізанням.`,t:[`baking`],m:40,i:[]}];var d={slug:t,id:n,country:`VU`,region:o,servings:6,minutes:97,title:r,text:u,steps:m};export{i as country,d as default,n as id,s as minutes,o as region,l as servings,t as slug,m as steps,u as text,r as title};